using System;using System.Linq;using BeamScheduleFormatter;
class SlabEstimatorTests {
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);}
 static void Main(){var row=new SlabScheduleRow{Mark="S1",Thickness=125,Bars=Enumerable.Range(0,9).Select(n=>SlabBar.Parse("#10@250 C/C")).ToArray()};var cfg=new LengthConfiguration{FySmall=276,Input=new LengthInput{Fc=28,Round=25,Simplified=true}};
 var a=SlabEstimatorEngine.Calculate(row,"Test",4,5,2,true,0,20,cfg,1,1,1,1,3,6);Check(a.Measures.ConcreteTotal==5,"Slab concrete");Check(a.Measures.FormworkTotal==40,"Slab soffit");Check(a.Steel.Result.Lines.Count==12,"Missing full/curtailed/top/distribution components");Check(a.Steel.Result.Lines.Count(l=>l.Part.StartsWith("Top distribution"))==4,"Distribution scope");Check(a.Steel.Result.Lines.Single(l=>l.Part=="Bottom short FULL").PiecesPerBeam==21,"Spacing measured across wrong side");Check(a.Steel.Result.Lines.Single(l=>l.Part=="Bottom long FULL").PiecesPerBeam==17,"Long-direction spacing count");Check(a.Steel.Result.Lines.All(l=>Math.Abs(l.CutLength/.025-Math.Round(l.CutLength/.025))<1e-8),"Cuts not rounded UP25mm");var plan=CommercialBars.Allocate(new[]{a.Steel},cfg);Check(plan.All(x=>x.Choice!=null),"Unresolved stock plan");Check(Math.Abs(plan.Sum(x=>x.Net)-a.Steel.Result.Total)<1e-8,"Quantity applied twice");
 bool rejected=false;try{SlabEstimatorEngine.Calculate(row,"",4,5,1,true,1,20,cfg,1,1,1,1,0,0);}catch(ArgumentException){rejected=true;}Check(rejected,"Ordinary slab counted exposed-edge forms");var edge=SlabEstimatorEngine.Calculate(row,"",4,5,1,true,5,20,cfg,1,1,1,1,0,0,true);Check(edge.Measures.FormworkTotal==20.625,"Cantilever edge forms");Console.WriteLine("PASS: slab direction/spacing, populated bottom curtailed columns, top distribution strips, support counts, 25mm cuts, commercial purchase reconciliation and cantilever edge forms.");
 }
}
